const request = $input.first().json;
const headers = request.headers ?? {};
const query = request.query ?? {};

const authHeader =
  headers.authorization ??
  headers.Authorization ??
  "";

const tokenMatch = authHeader.match(/^Bearer\s+(.+)$/i);
const token = tokenMatch?.[1]?.trim() ?? "";

const errors = [];

if (!token) {
  errors.push("Missing or invalid Authorization Bearer token");
}

const TIMEZONE = "Africa/Cairo";
const DEFAULT_RANGE_DAYS = 30;
const MAX_RANGE_DAYS = 366;

const getCairoDate = (date = new Date()) => {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(date);

  const values = Object.fromEntries(
    parts.map(part => [part.type, part.value])
  );

  return `${values.year}-${values.month}-${values.day}`;
};

const shiftDate = (dateString, days) => {
  const date = new Date(`${dateString}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
};

const parseDate = (value, field) => {
  if (!value) return null;

  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    errors.push(`${field} must use YYYY-MM-DD format`);
    return null;
  }

  const date = new Date(`${value}T00:00:00Z`);

  if (
    Number.isNaN(date.getTime()) ||
    date.toISOString().slice(0, 10) !== value
  ) {
    errors.push(`${field} is not a valid date`);
    return null;
  }

  return value;
};

const today = getCairoDate();

let from = parseDate(query.from, "from");
let to = parseDate(query.to, "to");

to ??= today;
from ??= shiftDate(to, -(DEFAULT_RANGE_DAYS - 1));

if (from > to) {
  errors.push("'from' must be earlier than or equal to 'to'");
}

const rangeDays =
  Math.round(
    (Date.parse(`${to}T00:00:00Z`) -
     Date.parse(`${from}T00:00:00Z`)) / 86400000
  ) + 1;

if (rangeDays > MAX_RANGE_DAYS) {
  errors.push(`Date range cannot exceed ${MAX_RANGE_DAYS} days`);
}

const parseLimit = (value, fallback, max, field) => {
  if (value === undefined || value === "") return fallback;

  const number = Number(value);

  if (!Number.isInteger(number) || number < 1 || number > max) {
    errors.push(`${field} must be an integer between 1 and ${max}`);
    return fallback;
  }

  return number;
};

const topLimit = parseLimit(query.top_limit, 5, 20, "top_limit");
const recentLimit = parseLimit(query.recent_limit, 20, 100, "recent_limit");

return [{
  json: {
    valid: errors.length === 0,
    errors,
    token,
    from,
    to,
    range_days: rangeDays,
    top_limit: topLimit,
    recent_limit: recentLimit,
    timezone: TIMEZONE,
    default_range_days: DEFAULT_RANGE_DAYS,
    max_range_days: MAX_RANGE_DAYS
  }
}];

const response = $input.first().json;
const prepared = $('Prepare & Validate').first().json;

// Add the actual admin emails here.
const ADMIN_EMAILS = [
  // "admin@example.com"
];

const httpStatus = response.statusCode;
const user = response.body ?? response;

const reject = (statusCode, message) => [{
  json: {
    authorized: false,
    statusCode,
    error: message
  }
}];

// 1. Validate request parameters
if (!prepared.valid) {
  return reject(400, prepared.errors.join("; "));
}

// 2. Validate Supabase session
if (
  (httpStatus && httpStatus !== 200) ||
  !user?.id ||
  !user?.email
) {
  return reject(401, "Invalid or expired Supabase session");
}

// 3. Require confirmed email
if (!user.email_confirmed_at) {
  return reject(403, "Email address is not confirmed");
}

// 4. Check admin authorization
const email = user.email.toLowerCase();
const isAdminEmail = ADMIN_EMAILS
  .map(item => item.toLowerCase())
  .includes(email);

const hasAdminRole =
  user.app_metadata?.salespulse_role === "admin";

if (!isAdminEmail && !hasAdminRole) {
  return reject(403, "Admin access required");
}

// 5. Prepare dashboard query parameters
return [{
  json: {
    authorized: true,
    statusCode: 200,
    user: {
      id: user.id,
      email: user.email
    },
    filters: {
      from: prepared.from,
      to: prepared.to,
      top_limit: prepared.top_limit,
      recent_limit: prepared.recent_limit,
      timezone: prepared.timezone,
      default_range_days: prepared.default_range_days,
      max_range_days: prepared.max_range_days,
      interest_window_hours: prepared.interest_window_hours
    }
  }
}];

